import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.BW2T23B9.js";const p=JSON.parse('{"title":"课程编辑器","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editor.md","filePath":"guide/editor.md","lastUpdated":1787830168000}'),r={name:"guide/editor.md"};function l(n,e,d,s,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="课程编辑器" tabindex="-1">课程编辑器 <a class="header-anchor" href="#课程编辑器" aria-label="Permalink to &quot;课程编辑器&quot;">​</a></h1><p>课程编辑器是桌面工具（<code>tool/gui</code>），不进 App 本体。老师或作者在本机打开课程文件夹，改 Section / Unit / Lesson，保存时走同一套校验。</p><p>产品页演示见 <a href="./../../editor.html">editor.html</a>。教师逐步操作见 <a href="/docs/authoring/teacher-guide">教师指南</a>。</p><h2 id="能改什么" tabindex="-1">能改什么 <a class="header-anchor" href="#能改什么" aria-label="Permalink to &quot;能改什么&quot;">​</a></h2><ul><li><strong>三级课程树</strong>：拖拽、复制、套用预设，结构和 App 里看到的一致。</li><li><strong>课时蓝图</strong>：intro / practice / listening / reading 等模板用表单和流程图编。</li><li><strong>课程工坊</strong>：从教材抽知识点，或从空白生成一节课，导入前先看 diff。</li><li><strong>教师试做</strong>：在桌面上把学员会做到的题点一遍。</li></ul><h2 id="推荐流程" tabindex="-1">推荐流程 <a class="header-anchor" href="#推荐流程" aria-label="Permalink to &quot;推荐流程&quot;">​</a></h2><ol><li>打开本地课程目录（例如 <code>turkish/</code>）。</li><li>在树里选一课，改名称、先修、题型和题目。</li><li>保存并校验；失败会回滚，避免写出坏 JSON。</li><li>用教师模式试做，再发布。</li></ol><p>课程内容的真理源是 JSON 文件，编辑器只是可视化前端。App 启动时把 JSON 写入本地 SQLite 缓存；改了内容版本号后会重新导入。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/authoring/course-layout">课程目录约定</a></li><li><a href="/docs/guide/lesson-types">课型说明</a></li></ul>',10)])])}const _=a(r,[["render",l]]);export{p as __pageData,_ as default};
